def asignar_sucursal_estaciones_y_ventas(apps, schema_editor):
    EstacionTrabajo = apps.get_model("ventas", "EstacionTrabajo")
    Venta = apps.get_model("ventas", "Venta")
    Sucursal = apps.get_model("empresas", "Sucursal")
    Caja = apps.get_model("caja", "Caja")

    def sucursal_empresa(empresa_id):
        suc = Sucursal.objects.filter(empresa_id=empresa_id, es_principal=True).first()
        if suc:
            return suc
        return Sucursal.objects.filter(empresa_id=empresa_id).order_by("id").first()

    empresa_ids = (
        EstacionTrabajo.objects.filter(sucursal__isnull=True)
        .values_list("empresa_id", flat=True)
        .distinct()
    )
    for empresa_id in empresa_ids:
        suc = sucursal_empresa(empresa_id)
        if suc:
            EstacionTrabajo.objects.filter(empresa_id=empresa_id, sucursal__isnull=True).update(
                sucursal_id=suc.id
            )

    ventas_sin_sucursal = Venta.objects.filter(sucursal__isnull=True).select_related(
        "estacion_trabajo"
    )
    for venta in ventas_sin_sucursal.iterator():
        suc_id = None
        estacion = getattr(venta, "estacion_trabajo", None)
        if estacion and estacion.sucursal_id:
            suc_id = estacion.sucursal_id
        else:
            suc = sucursal_empresa(venta.empresa_id)
            suc_id = suc.id if suc else None
        if suc_id:
            Venta.objects.filter(pk=venta.pk).update(sucursal_id=suc_id)

    for caja in Caja.objects.filter(estacion_trabajo__isnull=True):
        qs = EstacionTrabajo.objects.filter(empresa_id=caja.empresa_id)
        if caja.sucursal_id:
            qs = qs.filter(sucursal_id=caja.sucursal_id)
        # Solo vincular si hay una estación y una caja: si hay más TPV que cajas,
        # la caja queda compartida (sin estación) para no dejar un TPV sin caja.
        if qs.count() != 1:
            continue
        otras_cajas = Caja.objects.filter(
            empresa_id=caja.empresa_id,
            sucursal_id=caja.sucursal_id,
        ).exclude(pk=caja.pk).count()
        if otras_cajas:
            continue
        caja.estacion_trabajo_id = qs.first().id
        caja.save(update_fields=["estacion_trabajo"])


